SELECT set_config('test.cmd.original_auth',session_user,true);
SELECT set_config('app.test_time','',true);
SELECT set_config('test.cmd.grant',(SELECT id::text FROM core.membership_role_grants WHERE membership_id=test.id('new-fin-role') AND role_code='accountant' AND revoked_at IS NULL),true);
SELECT set_config('test.cmd.ownergrant',(SELECT g.id::text FROM core.memberships m JOIN core.membership_role_grants g ON g.membership_id=m.id WHERE m.org_id=test.org('TC-B01') AND m.user_id=test.person('Nguyễn Thị Năm') AND g.role_code='owner' AND g.revoked_at IS NULL LIMIT 1),true);
SET LOCAL SESSION AUTHORIZATION db_test_buyer;
SELECT test.expect_error('M12 tổ chức khác không thu hồi vai', $$SELECT cmd.revoke_member_role(current_setting('test.cmd.grant')::uuid)$$,'KHONG_CO_QUYEN');
RESET SESSION AUTHORIZATION; RESET ROLE;
DO $$ BEGIN EXECUTE format('SET LOCAL SESSION AUTHORIZATION %I',current_setting('test.cmd.original_auth')); END $$;
RESET ROLE;
SET LOCAL SESSION AUTHORIZATION db_test_seller;
SELECT cmd.revoke_member_role(current_setting('test.cmd.grant')::uuid);
SELECT test.expect_error('M12 không thu hồi chủ cuối cùng', $$SELECT cmd.revoke_member_role(current_setting('test.cmd.ownergrant')::uuid)$$,'ck_last_owner');
RESET SESSION AUTHORIZATION; RESET ROLE;
DO $$ BEGIN EXECUTE format('SET LOCAL SESSION AUTHORIZATION %I',current_setting('test.cmd.original_auth')); END $$;
RESET ROLE;
SELECT test.check('M12 thu hồi giữ lịch sử và loại khỏi vai hiệu lực',EXISTS(SELECT 1 FROM core.membership_role_grants WHERE id=current_setting('test.cmd.grant')::uuid AND revoked_by=test.person('Nguyễn Thị Năm') AND revoked_at IS NOT NULL) AND NOT EXISTS(SELECT 1 FROM core.membership_roles WHERE membership_id=test.id('new-fin-role') AND role_code='accountant'));
SELECT set_config('test.cmd.expireoffer',(SELECT id::text FROM core.offers WHERE code='CMD-OFFER'),true);
INSERT INTO core.deadlines(id,kind,entity,entity_id,due_at,created_at) VALUES(test.id('CMD-FUTURE-HAN'),'lot_visibility','lot',(SELECT id FROM core.lots WHERE code='CMD-LOT'),now()+interval '1 day',now());
SELECT set_config('test.cmd.deadline',test.id('CMD-FUTURE-HAN')::text,true);
SET LOCAL SESSION AUTHORIZATION db_test_system;
SELECT test.expect_error('D01 không hết hạn sớm bằng tham số client', $$SELECT cmd.expire_deadline(current_setting('test.cmd.deadline')::uuid)$$,'ck_deadline_not_due');
RESET SESSION AUTHORIZATION; RESET ROLE;
DO $$ BEGIN EXECUTE format('SET LOCAL SESSION AUTHORIZATION %I',current_setting('test.cmd.original_auth')); END $$;
RESET ROLE;
INSERT INTO cmd.test_clock(at) VALUES(now()+interval '2 days');
SET LOCAL SESSION AUTHORIZATION db_test_system;
SELECT cmd.expire_deadline(current_setting('test.cmd.deadline')::uuid);
SELECT cmd.expire_deadline(current_setting('test.cmd.deadline')::uuid);
RESET SESSION AUTHORIZATION; RESET ROLE;
DO $$ BEGIN EXECUTE format('SET LOCAL SESSION AUTHORIZATION %I',current_setting('test.cmd.original_auth')); END $$;
RESET ROLE;
DELETE FROM cmd.test_clock;
SELECT test.check('D01 hết hạn lô qua clock thử và retry không lặp',(SELECT status='hidden' FROM core.lots WHERE code='CMD-LOT') AND (SELECT count(*)=1 FROM evt.state_history WHERE entity='lot' AND entity_id=(SELECT id FROM core.lots WHERE code='CMD-LOT') AND to_status='hidden'));
SELECT set_config('test.cmd.cancelorder',test.id('LS4')::text,true);
SET LOCAL SESSION AUTHORIZATION db_test_buyer;
SELECT set_config('test.cmd.cancel',cmd.request_cancel(current_setting('test.cmd.cancelorder')::uuid,'buyer_request','Thử hủy',false)::text,true);
SELECT test.expect_error('D01 người xin hủy không tự chấp nhận', $$SELECT cmd.answer_cancel(current_setting('test.cmd.cancel')::uuid,true)$$,'KHONG_CO_QUYEN');
RESET SESSION AUTHORIZATION; RESET ROLE;
DO $$ BEGIN EXECUTE format('SET LOCAL SESSION AUTHORIZATION %I',current_setting('test.cmd.original_auth')); END $$;
RESET ROLE;
SET LOCAL SESSION AUTHORIZATION db_test_seller;
SELECT cmd.answer_cancel(current_setting('test.cmd.cancel')::uuid,false);
RESET SESSION AUTHORIZATION; RESET ROLE;
DO $$ BEGIN EXECUTE format('SET LOCAL SESSION AUTHORIZATION %I',current_setting('test.cmd.original_auth')); END $$;
RESET ROLE;
SELECT test.check('D01 đối tác từ chối hủy không động vào tiền',(SELECT status='rejected' FROM core.cancellation_requests WHERE id=current_setting('test.cmd.cancel')::uuid) AND NOT EXISTS(SELECT 1 FROM core.bank_instructions WHERE order_id=test.id('LS4')));
SELECT test.check('M03 app không tự cấp receipt PIN/auth session',NOT has_function_privilege('db_test_buyer','cmd.record_reauthentication(uuid,uuid,text,text)','EXECUTE') AND NOT has_function_privilege('db_test_buyer','cmd.record_login_session(uuid,uuid,text,bytea,timestamptz,text,text)','EXECUTE'));
CREATE ROLE db_test_auth LOGIN NOSUPERUSER NOBYPASSRLS;
GRANT agiviet_auth_worker TO db_test_auth;
SELECT set_config('test.cmd.loginuser',test.person('Trần Thu Hà')::text,true),set_config('test.cmd.loginorg',test.org('TC-M01')::text,true),set_config('test.cmd.tokenhash',encode(digest('TEST-RANDOM-SESSION-TOKEN','sha256'),'hex'),true);
SELECT cmd.record_otp('CMD-LOGIN-OTP',test.person('Trần Thu Hà'),'login',jsonb_build_object('org_id',test.org('TC-M01'),'device_id','TEST-LOGIN-DEVICE','token_sha256',current_setting('test.cmd.tokenhash')),digest('TEST-HMAC','sha256'));
SELECT cmd.otp_verification('CMD-LOGIN-OTP',true);
SET LOCAL SESSION AUTHORIZATION db_test_auth;
SELECT set_config('test.cmd.session',cmd.record_login_session(current_setting('test.cmd.loginuser')::uuid,current_setting('test.cmd.loginorg')::uuid,'TEST-LOGIN-DEVICE',decode(current_setting('test.cmd.tokenhash'),'hex'),now()+interval '1 day','CMD-LOGIN-OTP')::text,true);
SELECT set_config('test.cmd.sessionfound',(SELECT id::text FROM cmd.lookup_session(decode(current_setting('test.cmd.tokenhash'),'hex'))),true);
RESET SESSION AUTHORIZATION; RESET ROLE;
DO $$ BEGIN EXECUTE format('SET LOCAL SESSION AUTHORIZATION %I',current_setting('test.cmd.original_auth')); END $$;
RESET ROLE;
SELECT test.check('M05 phiên đăng nhập bền vững dùng hash và OTP đã tiêu thụ',current_setting('test.cmd.session')=current_setting('test.cmd.sessionfound') AND EXISTS(SELECT 1 FROM app_auth.sessions WHERE id=current_setting('test.cmd.session')::uuid AND user_id=test.person('Trần Thu Hà')));

SET LOCAL SESSION AUTHORIZATION db_test_auth;
SELECT cmd.revoke_session(decode(current_setting('test.cmd.tokenhash'),'hex'));
SELECT set_config('test.cmd.sessioncount',(SELECT count(*)::text FROM cmd.lookup_session(decode(current_setting('test.cmd.tokenhash'),'hex'))),true);
RESET SESSION AUTHORIZATION; RESET ROLE;
DO $$ BEGIN EXECUTE format('SET LOCAL SESSION AUTHORIZATION %I',current_setting('test.cmd.original_auth')); END $$;
RESET ROLE;
SELECT test.check('M05 token thu hồi không dùng lại được',current_setting('test.cmd.sessioncount')='0');
SELECT test.check('D01 mọi entry point mới SECURITY DEFINER, search_path cố định',NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='cmd' AND (has_function_privilege('agiviet_app',p.oid,'EXECUTE') OR has_function_privilege('agiviet_orchestrator',p.oid,'EXECUTE')) AND (NOT p.prosecdef OR NOT EXISTS(SELECT 1 FROM unnest(p.proconfig) c WHERE c LIKE 'search_path=%'))));
-- Nhu cầu tạo nguyên tử các dòng và giá kín dưới login app.
SELECT set_config('test.cmd.demanddata',jsonb_build_object('code','CMD-DEMAND','segment_code','processor','product_id',(SELECT product_id FROM core.lots WHERE code='CMD-LOT'),'profile_version',1,'needed_during',daterange(current_date,current_date+7),'delivery_mode','delivered')::text,true),
 set_config('test.cmd.demandlines',jsonb_build_array(jsonb_build_object('grade_code',(SELECT grade_code FROM core.lots WHERE code='CMD-LOT'),'qty',500000,'max_price_vnd',30000))::text,true);
SET LOCAL SESSION AUTHORIZATION db_test_buyer;
SELECT cmd.create_demand(current_setting('test.cmd.demanddata')::jsonb,current_setting('test.cmd.demandlines')::jsonb);
RESET SESSION AUTHORIZATION; RESET ROLE;
DO $$ BEGIN EXECUTE format('SET LOCAL SESSION AUTHORIZATION %I',current_setting('test.cmd.original_auth')); END $$;
RESET ROLE;
SELECT test.check('D01 nhu cầu mở cùng dòng và giá kín',EXISTS(SELECT 1 FROM core.demands d JOIN core.demand_lines l ON l.demand_id=d.id JOIN core.demand_line_max_prices p ON p.demand_line_id=l.id WHERE d.code='CMD-DEMAND' AND d.status='open' AND d.buyer_org_id=test.org('TC-M01') AND l.qty=500000 AND p.max_price_vnd=30000));
